actions.script:
organizationPartyId=null
def requested=ec.user.getPreference('ACTIVE_ORGANIZATION')
if(!requested || requested=='_NA_') return
if(ec.user.isInGroup('ADMIN')) {
    def party=ec.entity.find('mantle.party.Party').condition('partyId',requested).disableAuthz().one()
    def internal=ec.entity.find('mantle.party.PartyRole').condition('partyId',requested).condition('roleTypeId','OrgInternal').disableAuthz().count()
    if(party && party.disabled!='Y' && internal && ec.entity.find('mantle.party.Organization').condition('partyId',requested).disableAuthz().one()) organizationPartyId=requested
    return
}
def partyId=ec.user.userAccount?.partyId
if(!partyId) return
def scope=ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo').parameters([partyId:partyId]).disableAuthz().call()
if(requested==scope?.activeOrgId && (scope?.userOrgIds ?: []).contains(requested)) organizationPartyId=requested

order=ec.entity.find('mantle.order.OrderHeader').condition('orderId',orderId).disableAuthz().forUpdate(editable).one()
def parts=ec.entity.find('mantle.order.OrderPart').condition('orderId',orderId).disableAuthz().list()
part=parts.size()==1 ? parts[0] : null
def org=ec.service.sync().name('zenith.purchase.OperationsServices.get#PurchaseOrganization').call().organizationPartyId
def vendor=part?.vendorPartyId ? ec.entity.find('mantle.party.Party').condition('partyId',part.vendorPartyId).disableAuthz().one() : null
// This UI creates one buying part ('01'); never treat a sales or mixed-tenant order as a PO.
allowed=order!=null && part!=null && part.orderPartSeqId=='01' && vendor!=null && vendor.ownerPartyId==part.customerPartyId &&
    (ec.user.isInGroup('ADMIN') || (org && part.customerPartyId==org))
if(editable && order?.statusId!='OrderOpen') allowed=false
if(!allowed && errorOnDenied!='N') ec.message.addError('Purchase order not found, outside your organization, or closed for editing.')

orderIds=[]
if(!scope.organizationPartyId) return
def candidates=ec.entity.find('mantle.order.OrderPart').condition('customerPartyId',scope.organizationPartyId).disableAuthz().list().orderId.unique()
if(!candidates) return
def groups=ec.entity.find('mantle.order.OrderPart').condition('orderId','in',candidates).disableAuthz().list().groupBy{it.orderId}
def vendors=ec.entity.find('mantle.party.Party').condition('ownerPartyId',scope.organizationPartyId).disableAuthz().list().partyId as Set
groups.each {id,parts -> if(parts.size()==1 && parts[0].orderPartSeqId=='01' && vendors.contains(parts[0].vendorPartyId)) orderIds.add(id)}

def row=ec.entity.find('mantle.order.OrderHeader').condition('orderId',orderId).forUpdate(true).one()
if(updates.orderName!=null && row.statusId!='OrderOpen') {ec.message.addError('Issued PO details cannot be edited.');return}
if(updates.statusId && updates.statusId!=row.statusId) {
    def flow=ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId','Default').condition('statusId',row.statusId).condition('toStatusId',updates.statusId).one()
    if(!flow || (flow.userPermissionId && !ec.user.hasPermission(flow.userPermissionId))) {ec.message.addError('Select an available PO workflow status.');return}
    ec.service.sync().name('mantle.order.OrderServices.update#OrderStatus').parameters([orderId:orderId,statusId:updates.statusId]).call()
    if(ec.message.hasError()) return
}
if(updates.orderName!=null) ec.service.sync().name('update#mantle.order.OrderHeader').parameters([orderId:orderId,orderName:updates.orderName]).call()

def date
try {date=java.sql.Timestamp.valueOf(java.time.LocalDate.parse(receiptDate.toString().trim()).atStartOfDay())} catch(Exception ignored) {ec.message.addError('Enter a valid receipt date.');return}
def amounts=[freightAmount,insuranceAmount,customsDutyAmount]
if(amounts.any {it!=null && it<0}) {ec.message.addError('Landed surcharges cannot be negative.');return}
def row=ec.entity.makeValue('zenith.erp.purchase.GoodsReceiptNote').setAll([purchaseOrderId:purchaseOrderId,vendorPartyId:access.part.vendorPartyId,receiptDate:date,freightAmount:freightAmount,insuranceAmount:insuranceAmount,customsDutyAmount:customsDutyAmount]).setSequencedIdPrimary().create()
grnId=row.grnId
